CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(191) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'admin',status VARCHAR(30) NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,description TEXT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,excerpt TEXT NULL,markdown_content MEDIUMTEXT NOT NULL,rendered_html_cache MEDIUMTEXT NULL,featured_image VARCHAR(500) NULL,status ENUM('draft','scheduled','published','archived') NOT NULL DEFAULT 'draft',author_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NULL,meta_title VARCHAR(255) NULL,meta_description VARCHAR(500) NULL,canonical_url VARCHAR(500) NULL,focus_keyword VARCHAR(191) NULL,og_title VARCHAR(255) NULL,og_description VARCHAR(500) NULL,og_image VARCHAR(500) NULL,robots_index TINYINT(1) NOT NULL DEFAULT 1,robots_follow TINYINT(1) NOT NULL DEFAULT 1,published_at DATETIME NULL,scheduled_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,INDEX idx_posts_status_published(status,published_at),INDEX idx_posts_scheduled(scheduled_at),FULLTEXT INDEX ft_posts_search(title,excerpt,markdown_content),CONSTRAINT fk_posts_author FOREIGN KEY(author_id) REFERENCES users(id),CONSTRAINT fk_posts_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(191) NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS post_tags (post_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(post_id,tag_id),INDEX idx_post_tags_tag(tag_id),CONSTRAINT fk_pt_post FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,CONSTRAINT fk_pt_tag FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL UNIQUE,mime_type VARCHAR(100) NOT NULL,extension VARCHAR(10) NOT NULL,size BIGINT UNSIGNED NOT NULL,width INT UNSIGNED NULL,height INT UNSIGNED NULL,alt_text VARCHAR(255) NULL,caption TEXT NULL,path VARCHAR(500) NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,CONSTRAINT fk_media_user FOREIGN KEY(uploaded_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(191) NOT NULL UNIQUE,setting_value MEDIUMTEXT NULL,setting_type VARCHAR(30) NOT NULL DEFAULT 'string',is_public TINYINT(1) NOT NULL DEFAULT 0,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME NOT NULL,INDEX idx_reset_expiry(expires_at),CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(191) NOT NULL,ip_hash CHAR(64) NOT NULL,attempted_at DATETIME NOT NULL,successful TINYINT(1) NOT NULL,INDEX idx_login_limit(email,ip_hash,attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(100) NULL,entity_id BIGINT UNSIGNED NULL,metadata_json JSON NULL,ip_hash CHAR(64) NULL,created_at DATETIME NOT NULL,INDEX idx_audit_entity(entity_type,entity_id),CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS migrations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,migration VARCHAR(255) NOT NULL UNIQUE,ran_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
